def validate_reference(value, run, check_text_units=True, geometry_warnings=None):
    from validate import analysis_check
    analysis_check(value['analysis'], read(run / 'input.json'))
    validate_backgrounds(value['analysis'])
    for item in value['analysis']['objects']:
        if item['kind'] == 'overlay' and item.get('method', 'local') == 'local' and not item.get('style', {}).get('shape'):
            raise ValueError(item['id'] + ': local overlay requires an explicit supported shape')
    if check_text_units:
        validate_text_units(value['text_units'], value['analysis'], geometry_warnings)


def validate_bindings(value, analysis, run):
    from validate import bindings_check
    bindings_check(value, analysis, read(run / 'prepared/catalog.json'))




def validate_bundle(value, run, check_text_units=True):
    validate_reference(value, run, check_text_units)
    validate_bindings(value['bindings'], value['analysis'], run)


def validate_backgrounds(analysis):
    """Validate declared production routes, leaving visual classification to the VLM."""
    background_ids = set()
    for item in analysis['objects']:
        kind = item['kind']; route = item.get('background_type'); style = item.get('style', {})
        if kind == 'background':
            if route not in {'simple_design', 'complex_design', 'reference_clean'}:
                raise ValueError(item['id'] + ': background requires simple_design, reference_clean or legacy complex_design')
            if route == 'reference_clean':
                if item.get('method') != 'extract':
                    raise ValueError(item['id'] + ': reference_clean background requires method=extract')
            elif item.get('method') != 'local' or not style.get('fill'):
                raise ValueError(item['id'] + ': design background requires method=local and explicit style.fill; extraction/placeholder/default white is forbidden')
            if style.get('shape', 'rectangle') not in {'rectangle', 'paper'}:
                raise ValueError(item['id'] + ': background uses rectangle/paper; independent shapes belong to overlays')
        elif route == 'photographic':
            if kind != 'photo' or item.get('mode', 'cover') not in {'cover', 'feather', 'stroke'}:
                raise ValueError(item['id'] + ': photographic background must be a bound photo in cover/feather/stroke mode; cutout is a foreground photo')
            if item.get('method', 'local') != 'local':
                raise ValueError(item['id'] + ': photographic background uses customer pixels, not reference extraction')
        elif route is not None:
            raise ValueError(item['id'] + ': background_type only applies to customer photos or fixed backgrounds')
        if kind == 'background' or route == 'photographic':
            background_ids.add(item['id'])
    objects = {item['id']: item for item in analysis['objects']}
    preceding_foreground = []
    for oid in analysis['layer_order']:
        if oid not in background_ids:
            preceding_foreground.append(objects[oid])
            continue
        # Disjoint collage panels may be interleaved with another panel's text.
        # Only a positive-area intersection can obscure that earlier foreground.
        x0, y0, x1, y1 = objects[oid]['bbox']
        for foreground in preceding_foreground:
            fx0, fy0, fx1, fy1 = foreground['bbox']
            if max(x0, fx0) < min(x1, fx1) and max(y0, fy0) < min(y1, fy1):
                raise ValueError(oid + ': background layers must precede overlapping foreground ' + foreground['id'])


def validate_text_units(units, analysis, geometry_warnings=None):
    """Check declared text ownership, without pretending to infer image semantics."""
    from collage.text_units import validate
    validate(units, analysis, geometry_warnings)


def _preserve_box_records(before, after, key, editable, label):
    """Full replacements may correct geometry and append records, never drop content."""
    updated = {item[key]: item for item in after}
    for item in before:
        identifier = item[key]
        if identifier not in updated:
            raise ValueError(f'boxes must preserve existing {label} ID: {identifier}')
        changed = {field for field in item.keys() | updated[identifier].keys()
                   if field not in editable and (field not in item or field not in updated[identifier]
                                                or item[field] != updated[identifier][field])}
        if changed:
            raise ValueError(f'boxes cannot change {label} {identifier} fields: ' + ', '.join(sorted(changed)))


def validate_box_decision(value, current, run, geometry_warnings=None):
    if value['decision'] == 'replace':
        from copy import deepcopy
        from collage.workflow.support.reference_cleanup import normalize
        before, after = deepcopy(current['analysis']), value['analysis']
        # Compare metadata in the same normalized form as an incoming reply.
        # Existing legacy null/empty OCR fields carry no visual content.
        normalize({'analysis': before})
        if {k: v for k, v in before.items() if k not in {'objects', 'layer_order'}} != {
                k: v for k, v in after.items() if k not in {'objects', 'layer_order'}}:
            raise ValueError('boxes must preserve analysis metadata and reference_size')
        # The inner photo aperture is geometry too. Its containment and photo-only
        # ownership are still checked by validate_reference below.
        _preserve_box_records(before['objects'], after['objects'], 'id', {'bbox', 'window_bbox', 'rotation'}, 'object')
        old_ids = {item['id'] for item in before['objects']}
        if [oid for oid in after['layer_order'] if oid in old_ids] != before['layer_order']:
            raise ValueError('boxes must preserve existing relative layer_order; only insert missing objects')
        _preserve_box_records(current['text_units'], value['text_units'], 'id', {'bbox'}, 'text unit')
        validate_reference(value, run, geometry_warnings=geometry_warnings)
        if 'photo_windows' in current or 'photo_windows' in value:
            from photo_windows import resolve_seams
            if 'photo_windows' not in value:
                raise ValueError('replace must include the complete photo_windows plan')
            if 'photo_windows' not in current:
                raise ValueError('boxes cannot create a photo_windows plan when none was supplied')
            # Geometry can reduce the overlap supporting an existing fade. The
            # program owns that adjustment; the model still cannot redesign a
            # window. Build the expected plan from original windows plus new slots.
            original = {p['photo_id']: p for p in current['photo_windows']['photos']}
            baseline = deepcopy(value['photo_windows'])
            baseline['photos'] = [deepcopy(original.get(p['photo_id'], p)) for p in baseline['photos']]
            resolved, notes = resolve_seams(baseline, after)
            expected = {p['photo_id']: p for p in resolved['photos']}
            echoed = deepcopy(value['photo_windows']['photos'])
            for spec in echoed:
                oid = spec['photo_id']
                # Cached accepted replies and apply/replay already contain the
                # deterministic adjustment. Accept that exact result as well.
                if oid in original and spec == expected[oid]:
                    spec.clear()
                    spec.update(deepcopy(original[oid]))
            _preserve_box_records(current['photo_windows']['photos'], echoed,
                                  'photo_id', set(), 'photo window')
            value['photo_windows'] = resolved
            if geometry_warnings is not None:
                geometry_warnings.extend({'code': 'boxes_seam_adjusted', 'message': note} for note in notes)
    elif any(key in value and value[key] != current.get(key) for key in ['analysis', 'bindings', 'text_units', 'photo_windows']):
        raise ValueError('keep cannot change analysis, bindings, text_units or photo_windows; use replace for a correction')
    # Some providers echo unchanged optional fields. Exact echoes authorize no mutation.


def validate_review(value, scene, allow_adjustments=True):
    from validate import review_check
    ids = {o['id'] for o in scene['objects']}
    issues = value.get('issues', [])
    if len({i['id'] for i in issues}) != len(issues) or any(i['id'] not in ids for i in issues):
        raise ValueError('Issues must reference unique existing scene IDs')
    adjustments = value.get('adjustments', [])
    order = value.get('layer_order', [])
    if not allow_adjustments and (adjustments or order):
        raise ValueError('Final review cannot request another adjustment')
    if value['verdict'] == 'pass' and (issues or adjustments or order):
        raise ValueError('pass cannot contain unresolved issues or unapplied changes')
    if value['verdict'] == 'needs_changes' and not (issues or adjustments or order):
        raise ValueError('needs_changes requires specific object issues')
    if adjustments or order:
        check = {'schema_version': 'collage-review-v1', 'render_id': '0'*16, 'verdict': 'needs_changes',
                 'summary': value['summary'], 'items': [{'id': i['id'], 'action': 'adjust',
                     'reason': i['reason'], 'changes': i['changes']} for i in adjustments]}
        if order:
            check['layer_order'] = order
        review_check(check, scene)

collage/contracts.py.text:
"""Closed data contracts shared by model requests and local validation."""

from copy import deepcopy
import sys
from collage.config import ROOT, ENGINE
from collage.storage import read

if str(ENGINE) not in sys.path:
    sys.path.insert(0, str(ENGINE))

STRING = {'type': 'string'}


def obj(properties, required=None):
    return {'type': 'object', 'properties': properties,
            'required': list(properties) if required is None else required, 'additionalProperties': False}


def array(items):
    return {'type': 'array', 'items': items}


def inline_schema(name):
    documents = {key: read(ROOT / 'engine' / 'schemas' / f'{key}.schema.json')
                 for key in ['analysis', 'bindings', 'review']}
    def expand(value, document):
        if isinstance(value, list):
            return [expand(v, document) for v in value]
        if not isinstance(value, dict):
            return value
        if '$ref' in value:
            uri, _, fragment = value['$ref'].partition('#')
            target = documents[uri.rsplit(':', 1)[-1]] if uri else document
            node = target
            for part in fragment.strip('/').split('/'):
                if part:
                    node = node[part.replace('~1', '/').replace('~0', '~')]
            return expand(node, target)
        return {k: expand(v, document) for k, v in value.items() if k not in {'$schema', '$id', '$defs'}}
    return expand(documents[name], documents[name])


ANALYSIS = inline_schema('analysis')
_object_schema = ANALYSIS['properties']['objects']['items']
_object_schema['properties']['kind']['description'] = (
    '需替换的摄影内容用 photo 绑定客户素材；固定模板背景可本地绘制或从参考清底，使用 background。'
    '普通可编辑文字才用 text；固定艺术字、完整文字标签及装饰用 overlay。'
    '需要独立提取的单窗装饰相框用 frame，method=extract，photo_id 必须指向承载照片；简单几何单色轮廓属于 photo。')
_object_schema['properties']['description']['description'] = (
    '描述完整制作单元及实际素材边界。独立贴纸不因重叠合并；合并须写明共同载体或整体设计依据、成员及内部遮挡。')
_object_schema.setdefault('allOf', []).extend([{'if': {'properties': {'kind': {'const': 'text'}}, 'required': ['kind']},
                          'then': {'required': ['text', 'text_status'],
                                   'properties': {'method': {'const': 'local'}}}}])
_object_schema['allOf'] += [
    # These restrictions already exist in engine validation. Put them in the
    # model contract as well so strict-output providers can prevent the mistakes.
    {'if': {'properties': {'kind': {'enum': ['background', 'text', 'overlay', 'frame']}},
            'required': ['kind']},
     'then': {'properties': {'window_bbox': False, 'mode': False, 'appearance': False}}},
    {'if': {'properties': {'kind': {'enum': ['background', 'text', 'photo']}},
            'required': ['kind']},
     'then': {'properties': {'photo_id': False}}},
    {'if': {'properties': {'kind': {'const': 'background'}}, 'required': ['kind']},
     'then': {'required': ['background_type', 'method'], 'properties': {
         'background_type': {'enum': ['simple_design', 'complex_design', 'reference_clean']}}}},
    {'if': {'properties': {'background_type': {'const': 'photographic'}}, 'required': ['background_type']},
     'then': {'properties': {'kind': {'const': 'photo'}, 'mode': {'enum': ['cover', 'feather', 'stroke']},
                             'method': {'const': 'local'}}}},
    {'if': {'properties': {'background_type': {'enum': ['simple_design', 'complex_design']}},
            'required': ['background_type']},
     'then': {'required': ['style'], 'properties': {'kind': {'const': 'background'},
               'method': {'const': 'local'}, 'style': {'required': ['fill']}}}},
    {'if': {'properties': {'background_type': {'const': 'reference_clean'}}, 'required': ['background_type']},
     'then': {'properties': {'kind': {'const': 'background'}, 'method': {'const': 'extract'}}}},
]
BINDINGS = inline_schema('bindings')
# New selection calls must encode the crop they describe. Existing engine files
# retain their optional defaults for backwards compatibility.
BINDING_PLAN = deepcopy(BINDINGS)
BINDING_PLAN['properties']['photos']['items']['required'] += ['crop_center', 'source_crop', 'mirror_x']
STYLE = deepcopy(ANALYSIS['properties']['objects']['items']['properties']['style'])
CHANGES = inline_schema('review')['properties']['items']['items']['properties']['changes']
# Revision nodes only expose the finite style controls they can safely execute.
# Rich shape/path construction belongs to initial analysis or explicit screening.
CHANGES['properties']['style']['properties'] = {
    k: v for k, v in CHANGES['properties']['style']['properties'].items()
    if k in {'fill', 'stroke', 'stroke_width', 'font', 'font_size', 'bold', 'italic',
             'opacity', 'align', 'line_spacing', 'corner_radius'}
}
IDENTIFIER = deepcopy(ANALYSIS['properties']['objects']['items']['properties']['id'])
TEXT_UNIT = obj({
    'id': IDENTIFIER,
    'bbox': deepcopy(ANALYSIS['properties']['objects']['items']['properties']['bbox']),
    'content': {'type': ['string', 'null']},
    'treatment': {'enum': ['plain_text', 'editable_label', 'fixed_artwork']},
    'has_backing': {'type': 'boolean'},
    'decorative_lettering': {'type': 'boolean'},
    'edit_requested': {'type': 'boolean'},
    'text_id': {'anyOf': [IDENTIFIER, {'type': 'null'}]},
    'carrier_id': {'anyOf': [IDENTIFIER, {'type': 'null'}],
                   'description': 'fixed_artwork 必须指向已建立的 kind=overlay/frame, method=extract 对象，不能指向 text；框体上的印字随 frame 保留'},
    'reason': STRING,
})
TEXT_UNITS = array(TEXT_UNIT)
REFERENCE = obj({'analysis': ANALYSIS, 'text_units': TEXT_UNITS})
BUNDLE = obj({'analysis': ANALYSIS, 'bindings': BINDINGS, 'text_units': TEXT_UNITS})
from window_contract import SCHEMA as PHOTO_WINDOWS
BOXES = obj({'decision': {'enum': ['keep', 'replace']}, 'summary': STRING,
             'analysis': ANALYSIS, 'text_units': TEXT_UNITS,
             'photo_windows': PHOTO_WINDOWS}, ['decision', 'summary'])
ISSUE = obj({'id': STRING, 'reason': STRING})
ADJUSTMENT = obj({'id': STRING, 'reason': STRING, 'changes': CHANGES})
REVIEW = obj({'verdict': {'enum': ['pass', 'needs_changes']}, 'summary': STRING,
              'issues': array(ISSUE), 'adjustments': array(ADJUSTMENT), 'layer_order': array(STRING)})
FINAL_REVIEW = obj({'verdict': {'enum': ['pass', 'needs_changes']}, 'summary': STRING, 'issues': array(ISSUE)})
SCREEN = obj({'decisions': array(obj({'id': STRING, 'action': {'enum': ['keep', 'drop', 'backing']},
                                    'reason': STRING, 'photo_content': {'enum': ['present', 'absent', 'uncertain']},
                                    'embedded_ids': array(STRING)},
                                   ['id', 'action', 'reason', 'photo_content']))})
EDIT = obj({'decision': {'enum': ['edit', 'clarify', 'unsupported']}, 'summary': STRING, 'question': STRING,
            'changes': array(ADJUSTMENT), 'remove_ids': array(STRING), 'layer_order': array(STRING)})


def validate_reference(value, run, check_text_units=True, geometry_warnings=None):
    from validate import analysis_check
    analysis_check(value['analysis'], read(run / 'input.json'))
    validate_backgrounds(value['analysis'])
    for item in value['analysis']['objects']:
        if item['kind'] == 'overlay' and item.get('method', 'local') == 'local' and not item.get('style', {}).get('shape'):
            raise ValueError(item['id'] + ': local overlay requires an explicit supported shape')
    if check_text_units:
        validate_text_units(value['text_units'], value['analysis'], geometry_warnings)


def validate_bindings(value, analysis, run):
    from validate import bindings_check
    bindings_check(value, analysis, read(run / 'prepared/catalog.json'))




def validate_bundle(value, run, check_text_units=True):
    validate_reference(value, run, check_text_units)
    validate_bindings(value['bindings'], value['analysis'], run)


def validate_backgrounds(analysis):
    """Validate declared production routes, leaving visual classification to the VLM."""
    background_ids = set()
    for item in analysis['objects']:
        kind = item['kind']; route = item.get('background_type'); style = item.get('style', {})
        if kind == 'background':
            if route not in {'simple_design', 'complex_design', 'reference_clean'}:
                raise ValueError(item['id'] + ': background requires simple_design, reference_clean or legacy complex_design')
            if route == 'reference_clean':
                if item.get('method') != 'extract':
                    raise ValueError(item['id'] + ': reference_clean background requires method=extract')
            elif item.get('method') != 'local' or not style.get('fill'):
                raise ValueError(item['id'] + ': design background requires method=local and explicit style.fill; extraction/placeholder/default white is forbidden')
            if style.get('shape', 'rectangle') not in {'rectangle', 'paper'}:
                raise ValueError(item['id'] + ': background uses rectangle/paper; independent shapes belong to overlays')
        elif route == 'photographic':
            if kind != 'photo' or item.get('mode', 'cover') not in {'cover', 'feather', 'stroke'}:
                raise ValueError(item['id'] + ': photographic background must be a bound photo in cover/feather/stroke mode; cutout is a foreground photo')
            if item.get('method', 'local') != 'local':
                raise ValueError(item['id'] + ': photographic background uses customer pixels, not reference extraction')
        elif route is not None:
            raise ValueError(item['id'] + ': background_type only applies to customer photos or fixed backgrounds')
        if kind == 'background' or route == 'photographic':
            background_ids.add(item['id'])
    objects = {item['id']: item for item in analysis['objects']}
    preceding_foreground = []
    for oid in analysis['layer_order']:
        if oid not in background_ids:
            preceding_foreground.append(objects[oid])
            continue
        # Disjoint collage panels may be interleaved with another panel's text.
        # Only a positive-area intersection can obscure that earlier foreground.
        x0, y0, x1, y1 = objects[oid]['bbox']
        for foreground in preceding_foreground:
            fx0, fy0, fx1, fy1 = foreground['bbox']
            if max(x0, fx0) < min(x1, fx1) and max(y0, fy0) < min(y1, fy1):
                raise ValueError(oid + ': background layers must precede overlapping foreground ' + foreground['id'])


def validate_text_units(units, analysis, geometry_warnings=None):
    """Check declared text ownership, without pretending to infer image semantics."""
    from collage.text_units import validate
    validate(units, analysis, geometry_warnings)


def _preserve_box_records(before, after, key, editable, label):
    """Full replacements may correct geometry and append records, never drop content."""
    updated = {item[key]: item for item in after}
    for item in before:
        identifier = item[key]
        if identifier not in updated:
            raise ValueError(f'boxes must preserve existing {label} ID: {identifier}')
        changed = {field for field in item.keys() | updated[identifier].keys()
                   if field not in editable and (field not in item or field not in updated[identifier]
                                                or item[field] != updated[identifier][field])}
        if changed:
            raise ValueError(f'boxes cannot change {label} {identifier} fields: ' + ', '.join(sorted(changed)))


def validate_box_decision(value, current, run, geometry_warnings=None):
    if value['decision'] == 'replace':
        from copy import deepcopy
        from collage.workflow.support.reference_cleanup import normalize
        before, after = deepcopy(current['analysis']), value['analysis']
        # Compare metadata in the same normalized form as an incoming reply.
        # Existing legacy null/empty OCR fields carry no visual content.
        normalize({'analysis': before})
        if {k: v for k, v in before.items() if k not in {'objects', 'layer_order'}} != {
                k: v for k, v in after.items() if k not in {'objects', 'layer_order'}}:
            raise ValueError('boxes must preserve analysis metadata and reference_size')
        # The inner photo aperture is geometry too. Its containment and photo-only
        # ownership are still checked by validate_reference below.
        _preserve_box_records(before['objects'], after['objects'], 'id', {'bbox', 'window_bbox', 'rotation'}, 'object')
        old_ids = {item['id'] for item in before['objects']}
        if [oid for oid in after['layer_order'] if oid in old_ids] != before['layer_order']:
            raise ValueError('boxes must preserve existing relative layer_order; only insert missing objects')
        _preserve_box_records(current['text_units'], value['text_units'], 'id', {'bbox'}, 'text unit')
        validate_reference(value, run, geometry_warnings=geometry_warnings)
        if 'photo_windows' in current or 'photo_windows' in value:
            from photo_windows import resolve_seams
            if 'photo_windows' not in value:
                raise ValueError('replace must include the complete photo_windows plan')
            if 'photo_windows' not in current:
                raise ValueError('boxes cannot create a photo_windows plan when none was supplied')
            # Geometry can reduce the overlap supporting an existing fade. The
            # program owns that adjustment; the model still cannot redesign a
            # window. Build the expected plan from original windows plus new slots.
            original = {p['photo_id']: p for p in current['photo_windows']['photos']}
            baseline = deepcopy(value['photo_windows'])
            baseline['photos'] = [deepcopy(original.get(p['photo_id'], p)) for p in baseline['photos']]
            resolved, notes = resolve_seams(baseline, after)
            expected = {p['photo_id']: p for p in resolved['photos']}
            echoed = deepcopy(value['photo_windows']['photos'])
            for spec in echoed:
                oid = spec['photo_id']
                # Cached accepted replies and apply/replay already contain the
                # deterministic adjustment. Accept that exact result as well.
                if oid in original and spec == expected[oid]:
                    spec.clear()
                    spec.update(deepcopy(original[oid]))
            _preserve_box_records(current['photo_windows']['photos'], echoed,
                                  'photo_id', set(), 'photo window')
            value['photo_windows'] = resolved
            if geometry_warnings is not None:
                geometry_warnings.extend({'code': 'boxes_seam_adjusted', 'message': note} for note in notes)
    elif any(key in value and value[key] != current.get(key) for key in ['analysis', 'bindings', 'text_units', 'photo_windows']):
        raise ValueError('keep cannot change analysis, bindings, text_units or photo_windows; use replace for a correction')
    # Some providers echo unchanged optional fields. Exact echoes authorize no mutation.


def validate_review(value, scene, allow_adjustments=True):
    from validate import review_check
    ids = {o['id'] for o in scene['objects']}
    issues = value.get('issues', [])
    if len({i['id'] for i in issues}) != len(issues) or any(i['id'] not in ids for i in issues):
        raise ValueError('Issues must reference unique existing scene IDs')
    adjustments = value.get('adjustments', [])
    order = value.get('layer_order', [])
    if not allow_adjustments and (adjustments or order):
        raise ValueError('Final review cannot request another adjustment')
    if value['verdict'] == 'pass' and (issues or adjustments or order):
        raise ValueError('pass cannot contain unresolved issues or unapplied changes')
    if value['verdict'] == 'needs_changes' and not (issues or adjustments or order):
        raise ValueError('needs_changes requires specific object issues')
    if adjustments or order:
        check = {'schema_version': 'collage-review-v1', 'render_id': '0'*16, 'verdict': 'needs_changes',
                 'summary': value['summary'], 'items': [{'id': i['id'], 'action': 'adjust',
                     'reason': i['reason'], 'changes': i['changes']} for i in adjustments]}
        if order:
            check['layer_order'] = order
        review_check(check, scene)

collage/vlm/coordinates.py.text:
"""Model-facing reference coordinates; persisted workflow documents stay in pixels.

Only declared global geometry is converted. In particular style.window.bbox,
polygon points, source_crop, stroke/fade ratios and rotations are not global boxes.
"""

from copy import deepcopy
import math
from collage.prompts.builder import reference_instructions as instructions

SLOT = '{{REFERENCE_COORDINATES}}'
VERSION = 2
# Deliberately explicit: Qwen2.5-VL and unknown future models must not match this.
NORMALIZED_MODELS = frozenset({'qwen/qwen3.8-flash', 'qwen/qwen3.8-max-0902',
                              'qwen3.8-flash', 'qwen3.8-max-0902', 'qwen3.8-max'})


def resolve_mode(model, setting='auto'):
    if setting not in {'auto', 'pixel', 'normalized_1000'}:
        raise ValueError('Unknown coordinate mode: ' + setting)
    return ('normalized_1000' if model in NORMALIZED_MODELS else 'pixel') if setting == 'auto' else setting


def model_context(context, mode):
    """Hide reference pixel dimensions only at the model boundary; never mutate canonical data."""
    value = deepcopy(context)
    if mode != 'normalized_1000':
        return value
    size = value.pop('reference_size', None)
    if isinstance(size, list) and len(size) == 2 and all(type(n) in (int, float) and n > 0 for n in size):
        value['reference_aspect_ratio'] = round(size[0] / size[1], 6)
    if isinstance(value.get('analysis'), dict):
        value['analysis'].pop('reference_size', None)
    for slot in value.get('photo_slots', []):
        width, height = slot.pop('width', None), slot.pop('height', None)
        if width is not None and height:
            slot.setdefault('aspect_ratio', round(width / height, 6))
    for asset in value.get('catalog', []):
        size = asset.pop('size', None)
        if size:
            asset['aspect_ratio'] = round(size[0] / size[1], 6)
    return value


def _records(document):
    """Yield named global rectangles only; never recursively scale arbitrary bbox keys."""
    if not isinstance(document, dict):
        return
    containers = [('', document)]
    if isinstance(document.get('analysis'), dict):
        containers.append(('analysis.', document['analysis']))
    for prefix, container in containers:
        for field in ('objects', 'text_units', 'photo_slots'):
            rows = container.get(field, [])
            if not isinstance(rows, list):
                continue
            for index, row in enumerate(rows):
                if not isinstance(row, dict):
                    continue
                for name in ('bbox', 'window_bbox') if field in {'objects', 'photo_slots'} else ('bbox',):
                    if name in row:
                        yield (prefix + field, row.get('id', row.get('slot_id', index)), name), row, name
    regions = document.get('crop_regions', [])
    if isinstance(regions, list):
        for index, row in enumerate(regions):
            if isinstance(row, dict) and 'crop_bbox' in row:
                yield ('crop_regions', row.get('photo_id', index), 'crop_bbox'), row, 'crop_bbox'
    for index, photo in enumerate(document.get('photos', [])):
        placement = photo.get('placement') if isinstance(photo, dict) else None
        if isinstance(placement, dict) and 'bbox' in placement:
            yield ('photo_placement', photo.get('photo_id', index), 'bbox'), placement, 'bbox'


def _check_box(box, size, label):
    if (not isinstance(box, list) or len(box) != 4 or
            any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in box)):
        raise ValueError(f'{label}: expected four finite coordinates')
    l, t, r, b = box
    if not (0 <= l < r <= size[0] and 0 <= t < b <= size[1]):
        raise ValueError(f'{label}: expected positive box within [0,0,{size[0]},{size[1]}]')


def _bbox_schemas(schema):
    """Only the global geometry fields in reference/boxes outputs."""
    props = schema.get('properties', {})
    analysis = props.get('analysis', {}).get('properties', {})
    fields = analysis.get('objects', {}).get('items', {}).get('properties', {})
    for name in ('bbox', 'window_bbox'):
        if name in fields:
            yield fields[name]
    units = props.get('text_units', {}).get('items', {}).get('properties', {})
    if 'bbox' in units:
        yield units['bbox']
    placement = props.get('photos', {}).get('items', {}).get('properties', {}).get('placement', {}).get('properties', {})
    if 'bbox' in placement:
        yield placement['bbox']


class ReferenceCoordinates:
    """Adapt one request; same instance decodes replies, retries and recovery candidates."""
    def __init__(self, context, mode, input_only=False):
        self.mode = mode
        self.input_only = input_only
        self.size = deepcopy(context.get('reference_size'))
        if (not isinstance(self.size, list) or len(self.size) != 2 or
                any(type(n) is not int or n <= 0 for n in self.size)):
            raise ValueError('Reference coordinate requests require actual reference_size')
        self.context = deepcopy(context)
        self.originals = {}
        self.sent = {}
        for key, row, name in _records(self.context):
            _check_box(row[name], self.size, str(key))
            self.originals[key] = deepcopy(row[name])
            if mode == 'normalized_1000':
                row[name] = [round(v / self.size[i % 2] * 1000, 8) for i, v in enumerate(row[name])]
            self.sent[key] = deepcopy(row[name])
        self.context['coordinate_space'] = mode
        # Give the window stage actual aspect ratios; normalized width/height are not aspect ratios.
        if isinstance(context.get('analysis'), dict) and 'photo_slots' not in self.context:
            self.context['photo_slots'] = []
            for item in context['analysis'].get('objects', []):
                if item.get('kind') == 'photo':
                    l, t, r, b = item['bbox']
                    self.context['photo_slots'].append({'slot_id': item['id'], 'width': r-l, 'height': b-t,
                                                       'aspect_ratio': round((r-l)/(b-t), 6)})
        self.context = model_context(self.context, mode)

    @property
    def metadata(self):
        value = {'mode': self.mode, 'canonical_mode': 'pixel', 'reference_size': self.size,
                 'scale': 1000 if self.mode == 'normalized_1000' else None, 'adapter_version': VERSION}
        # Preserve existing cache identities for stages that also output coordinates.
        if self.input_only:
            value['input_only'] = True
        return value

    def prompt(self, template):
        if template.count(SLOT) != 1:
            raise ValueError('Reference prompt must contain exactly one coordinate slot')
        return template.replace(SLOT, instructions(self.mode, self.input_only))

    def schema(self, canonical):
        schema = deepcopy(canonical)
        if self.input_only:
            return schema
        schema['properties']['coordinate_space'] = {'type': 'string', 'const': self.mode}
        schema['required'] = list(schema.get('required', [])) + ['coordinate_space']
        for box in _bbox_schemas(schema):
            box['items'] = {'type': 'number' if self.mode == 'normalized_1000' else 'integer',
                            'minimum': 0, 'maximum': 1000 if self.mode == 'normalized_1000' else max(self.size)}
            box['description'] = ('全局 [left,top,right,bottom]；' +
                                  ('0～1000 归一化坐标。' if self.mode == 'normalized_1000'
                                   else '原图像素；x<=reference_size[0]，y<=reference_size[1]。'))
        analysis = schema['properties'].get('analysis', {}).get('properties', {})
        if 'reference_size' in analysis:
            if self.mode == 'normalized_1000':
                del analysis['reference_size']
                node = schema['properties']['analysis']
                node['required'] = [key for key in node.get('required', []) if key != 'reference_size']
            else:
                analysis['reference_size']['const'] = self.size
        return schema

    def decode(self, raw):
        if self.input_only:
            return deepcopy(raw)
        if not isinstance(raw, dict) or raw.get('coordinate_space') != self.mode:
            raise ValueError('coordinate_space must match request: ' + self.mode)
        result = deepcopy(raw)
        result.pop('coordinate_space')
        if isinstance(result.get('analysis'), dict):
            analysis = result['analysis']
            if self.mode == 'normalized_1000' and 'reference_size' not in analysis:
                analysis['reference_size'] = deepcopy(self.size)
            if analysis.get('reference_size') != self.size:
                raise ValueError('reference_size must preserve the actual image dimensions')
        for key, row, name in _records(result):
            _check_box(row[name], [1000, 1000] if self.mode == 'normalized_1000' else self.size, str(key))
            if self.mode == 'normalized_1000':
                # Preserve untouched rectangles exactly, including immutable window_bbox fields.
                if key in self.sent and row[name] == self.sent[key]:
                    row[name] = deepcopy(self.originals[key])
                else:
                    row[name] = [round(v / 1000 * self.size[i % 2]) for i, v in enumerate(row[name])]
                _check_box(row[name], self.size, str(key) + ' converted pixels')
        return result

collage/workflow/context.py.text:
"""Durable, finite first-image workflow. The VLM never chooses executable commands."""

import os
from pathlib import Path
import shutil
import subprocess
import sys
import time
from collage.vlm.client import Client, ModelError
from collage.workflow.support.fallbacks import simple_bundle
from collage.config import Config, ENGINE, ROOT
from collage.storage import digest, now, read, save
from collage.workflow.options import normalize_options


class CommandError(RuntimeError):
    """An engine operation failed; distinct from a process interruption."""


class RunContext:
    def __init__(self, run, control=None, config=None, client=None, attempt=1, reveal=True,
                 bbox_refinement=None, screen=None):
        self.run = Path(run).resolve()
        self.control = Path(control).resolve() if control else self.run/'workflow'
        self.config = config or Config.load().for_run(self.run)
        self.client = client or Client(self.control/'vlm', self.config)
        self.attempt = attempt
        self.reveal = reveal
        self.state = read(self.control/'state.json')
        options_path = self.run/'workflow-options.json'
        saved_options = read(options_path) if options_path.is_file() else self.state.get('workflow_options')
        self.workflow_options = normalize_options(saved_options)
        overrides = {name: value for name, value in
                     (('bbox_refinement', bbox_refinement), ('screen', screen)) if value is not None}
        if overrides:
            requested = normalize_options({**self.workflow_options, **overrides})
            if saved_options is not None and requested != self.workflow_options:
                raise ValueError('工作流开关与任务快照不一致，请创建新任务')
            self.workflow_options = requested
        self.state.setdefault('steps', {})
        self.state.setdefault('started_at', now())
        self.started = time.monotonic()

    def warn(self, code, stage, message):
        entry = {'code': code, 'stage': stage, 'message': str(message)[:1500]}
        warnings = self.state.setdefault('warnings', [])
        if entry not in warnings:
            warnings.append(entry)
        save(self.control/'warnings.json', warnings)
        self.sync()

    def candidates(self, stage):
        return self.client.candidates(stage) if hasattr(self.client, 'candidates') else []

    def write_bundle(self, bundle):
        save(self.run/'analysis.json', bundle['analysis'])
        save(self.run/'bindings.json', bundle['bindings'])
        save(self.run/'text-units.json', bundle['text_units'])

    def write_reference(self, value):
        save(self.run/'analysis.json', value['analysis'])
        save(self.run/'text-units.json', value['text_units'])
        if 'photo_windows' in value:
            save(self.run/'photo-windows.json', value['photo_windows'])
        self.command('validate', '--analysis-only')

    def draft(self, reason):
        bundle = simple_bundle(self.run)
        self.state['draft_kind'] = 'simple_layout'
        self.warn('simple_layout', self.state.get('current_step', 'analyze'), reason)
        self.write_bundle(bundle)
        if (self.run/'photo-windows.json').exists():
            from photo_windows import defaults
            save(self.run/'photo-windows.json', defaults(bundle['analysis']))
        self.command('validate')

    def optional(self, stage, function, default=None):
        try:
            return function()
        except (ModelError, CommandError) as exc:
            self.warn('optional_stage_failed', stage, str(exc))
            if stage == 'screen':
                self.progress(4, 'skipped', '素材筛选未完成，保留当前成图并进入交付检查')
            return default

    def sync(self):
        self.state.update(model=self.config.model, controller='workflow-v9', attempt=self.attempt,
                          model_policy=self.config.model_policy(),
                          workflow_options=self.workflow_options,
                          updated_at=now(), usage=self.client.usage(), worker_pid=os.getpid())
        save(self.control/'state.json', self.state)
        # The workbench can read progress even when --control is outside the task.
        save(self.run/'workflow-progress.json', {
            'status': self.state.get('status'), 'current_step': self.state.get('current_step'),
            'worker_pid': self.state.get('worker_pid'),
            'error': self.state.get('error'), 'updated_at': self.state['updated_at'],
            'steps': {name: {k: value for k, value in step.items()
                             if k in {'status', 'started_at', 'finished_at', 'error'}}
                      for name, step in self.state['steps'].items()}})
        timing = {k: self.state[k] for k in ['model', 'model_policy', 'workflow_options', 'controller', 'status', 'started_at', 'updated_at', 'usage']}
        timing.update(elapsed_seconds=round(time.time()-__import__('datetime').datetime.fromisoformat(self.state['started_at']).timestamp(), 3))
        if self.state.get('finished_at'):
            timing['finished_at'] = self.state['finished_at']
        save(self.run/'workflow-timing.json', timing)

    def command(self, command, *args):
        allowed = {'validate', 'build', 'render', 'screen', 'review', 'progress'}
        if command not in allowed:
            raise ValueError('Unsupported workflow operation')
        env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', COLLAGE_CONTROLLER='workflow-v9',
                   COLLAGE_BEST_EFFORT='1')
        # Remove only a stale lock owned by this workflow request, never an active editor's lock.
        lock = self.run/'.write.lock'
        owner = read(lock)
        if owner and owner.get('request_id') == os.getenv('COLLAGE_REQUEST_ID', 'v9-cli'):
            from workbench.server.chat import process_alive
            if not process_alive(owner.get('pid')):
                lock.unlink(missing_ok=True)
        env.setdefault('COLLAGE_REQUEST_ID', 'v9-cli')
        try:
            result = subprocess.run([sys.executable, '-B', str(ENGINE/'workflow.py'), command,
                                 '--run', str(self.run), *map(str, args)], cwd=ROOT, env=env,
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0), timeout=1200)
        except subprocess.TimeoutExpired:
            raise CommandError(f'{command} 超时，已停止本次本地操作') from None
        logs = self.control/'commands'; logs.mkdir(parents=True, exist_ok=True)
        with (logs/(command+'.log')).open('ab') as handle:
            handle.write(result.stdout)
        if result.returncode:
            output = result.stdout.decode('utf-8', errors='replace')
            try:
                import json
                output = json.loads(output)['error']
            except (ValueError, KeyError):
                output = output[-1000:]
            raise CommandError(f'{command} 失败：{output[:1500]}')

    def progress(self, stage, status, summary):
        self.command('progress', '--stage', stage, '--status', status, '--summary', summary)

    def step(self, name, function):
        existing = self.state['steps'].get(name, {})
        if existing.get('status') == 'complete':
            return existing.get('value')
        self.state['current_step'] = name
        self.state['steps'][name] = {'status': 'running', 'started_at': existing.get('started_at', now())}
        self.sync()
        try:
            value = function()
        except (Exception, KeyboardInterrupt) as exc:
            if name in {'analyze', 'photo_windows', 'bind'}:
                self.state['steps'][name].update(status='failed', finished_at=now(), error=str(exc)[:1500])
                self.sync()
                self.progress(2, 'failed', str(exc)[:1500])
            raise
        self.state['steps'][name].update(status='complete', finished_at=now(), value=value)
        result = read(self.run/'result.json')
        if result.get('render_id'):
            self.state['last_render_id'] = result['render_id']
        self.sync()
        return value

    def restore_mutation(self, folder, manifest):
        for rel, existed in manifest['files'].items():
            target = (self.run/rel).resolve()
            if not target.is_relative_to(self.run):
                raise ValueError('Unsafe transaction path')
            if existed:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(folder/'before'/rel, target)
            else:
                target.unlink(missing_ok=True)

    def mutate(self, name, command, plan):
        """Rollback an interrupted local mutation before replay. Never rolls back remote extraction."""
        folder = self.control/'transactions'/name
        manifest_path = folder/'manifest.json'
        manifest = read(manifest_path)
        targets = ['scene.json', 'result.json', 'final.png', 'screening.json', 'assets/gate/report.json']
        # A failed render can overwrite tile files before it publishes final.png.
        # Snapshot the current render's resources too, so rollback remains verifiable.
        for item in read(self.run/'result.json').get('resources', []):
            for source in [item.get('file'), item.get('metadata', {}).get('content_mask')]:
                if source and Path(source).resolve().is_relative_to(self.run):
                    targets.append(str(Path(source).resolve().relative_to(self.run)))
                    receipt = Path(source).with_suffix('.json')
                    if receipt.is_file():
                        targets.append(str(receipt.resolve().relative_to(self.run)))
        targets += [str(p.relative_to(self.run)) for p in (self.run/'previews').rglob('*') if p.is_file()]
        if manifest:
            if manifest['plan_key'] != digest(plan):
                raise ValueError('Mutation plan changed during recovery')
            if manifest.get('committed'):
                return not manifest.get('rolled_back', False)
            self.restore_mutation(folder, manifest)
        else:
            files = {}
            for rel in targets:
                source = self.run/rel; files[rel] = source.is_file()
                if files[rel]:
                    target = folder/'before'/rel; target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(source, target)
            manifest = {'plan_key': digest(plan), 'files': files, 'committed': False}
            save(manifest_path, manifest)
        path = folder/'plan.json'; save(path, plan)
        try:
            self.command(command, '--file', path)
        except CommandError as exc:
            self.restore_mutation(folder, manifest)
            manifest.update(committed=True, rolled_back=True, error=str(exc))
            save(manifest_path, manifest)
            self.warn('mutation_rolled_back', name, '修改失败，已保留上一张可用成图：' + str(exc))
            return False
        manifest.update(committed=True, render_id=read(self.run/'result.json')['render_id'])
        save(manifest_path, manifest)
        return True

    def input_context(self):
        inp = read(self.run/'input.json'); catalog = read(self.run/'prepared/catalog.json')
        return {'reference_size': inp['reference_size'], 'instructions': inp.get('instructions', ''),
                'catalog': [{k: a[k] for k in ['id', 'size']} for a in catalog['assets']]}

    def analysis_images(self):
        return [('参考图', self.run/'prepared/reference.png')]

    def reference_context(self):
        return {'reference_size': read(self.run/'input.json')['reference_size']}

    def material_images(self):
        from common import verify_source
        from collage.vlm.coordinates import resolve_mode
        from PIL import Image, ImageOps
        config = self.config.for_stage('bind')
        mode = resolve_mode(config.model, config.coordinate_mode)
        catalog = read(self.run/'prepared/catalog.json')
        images = [
            (f'客户素材联系表 {i+1}', Path(path)) for i, path in enumerate(catalog['contact_sheets'])]
        folder = self.run/'prepared/vlm-materials'
        folder.mkdir(exist_ok=True)
        for asset in catalog['assets']:
            source = verify_source(asset)
            path = folder/(asset['id']+'.jpg')
            with Image.open(source) as raw:
                im = ImageOps.exif_transpose(raw).convert('RGB')
                im.thumbnail((1024, 1024))
                im.save(path, quality=90)
            label = f"客户素材 {asset['id']}"
            if mode == 'pixel':
                label += f" 原始尺寸 {asset['size']}"
            images.append((label, path))
        return images

    def current_context(self):
        scene = read(self.run/'scene.json'); result = read(self.run/'result.json')
        objects = []
        allowed = ['id', 'kind', 'label', 'description', 'bbox', 'rotation', 'style', 'method', 'mode',
                   'text', 'photo_id', 'parent_id', 'embedded_in', 'embedded_owner', 'recovery_owner', 'binding',
                   'background_type', 'photo_window_spec']
        for o in scene['objects']:
            objects.append({**{k: o[k] for k in allowed if k in o},
                            'extracted': bool(o.get('recovered')), 'fixed_window': bool(o.get('photo_window'))})
        gate = read(self.run/'assets/gate/report.json')
        return {**self.input_context(), 'objects': objects, 'layer_order': scene['layer_order'],
                'text_units': read(self.run/'text-units.json', []),
                'incomplete_objects': result.get('incomplete_objects', []),
                'program_issues': result.get('issues', []),
                'gate_records': [{k: r[k] for k in ['id', 'status', 'issues', 'warnings', 'text_candidates', 'window_checks'] if k in r}
                                 for r in gate.get('records', [])]}

    def review_images(self, sheets=False):
        result = read(self.run/'result.json')
        images = [('参考图', self.run/'prepared/reference.png'), ('当前成图', self.run/'final.png')]
        images += [(f'客户照片联系表 {i+1}（照片内的内容不是固定装饰）', Path(p))
                   for i, p in enumerate(read(self.run/'prepared/catalog.json').get('contact_sheets', []))]
        images += [(f'局部对照 {i+1}', Path(r['file'])) for i, r in enumerate(result.get('review_regions', []))]
        if sheets:
            candidates = result.get('extraction_sheets', []) + result.get('asset_gate_summary', {}).get('sheets', [])
            for i, entry in enumerate(candidates):
                path = entry.get('file') if isinstance(entry, dict) else entry
                if path and Path(path).is_file():
                    images.append((f'素材检查表 {i+1}', Path(path)))
        return images

collage/workflow/options.py.text:
"""Per-task workflow switches, independent of model and coordinate settings."""

from pathlib import Path
from collage.storage import read


DEFAULTS = {'bbox_refinement': False, 'screen': False}


def normalize_options(value=None):
    value = {} if value is None else value
    if not isinstance(value, dict) or set(value) - DEFAULTS.keys():
        raise ValueError('工作流开关字段无效')
    options = {**DEFAULTS, **value}
    for name, enabled in options.items():
        if type(enabled) is not bool:
            raise ValueError(name + ' 必须为 true 或 false')
    return options


def load_options(run):
    return normalize_options(read(Path(run)/'workflow-options.json'))

collage/workflow/stages/analyze.py.text:
"""阶段 1：参考图 -> 对象清单。保留返回顺序，校验字段、关联并编译。"""

from copy import deepcopy
import math
from jsonschema import Draft202012Validator
from collage import contracts, prompts
from collage.vlm.client import ModelError
from collage.vlm.coordinates import resolve_mode
from collage.storage import read, save
from collage.vlm.response_normalization import unwrap_object


VERSION = 'structure-analysis-v9-5'
ID = {'type': 'string', 'pattern': '^[a-z][a-z0-9_-]{0,63}$'}
COLOR = {'type': 'string', 'pattern': '^#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$'}


def execute(ctx):
    ctx.progress(2, 'running', '识别完整对象、范围、归属和层级')
    size = ctx.reference_context()['reference_size']
    mode = resolve_mode(ctx.config.for_stage('analyze').model, ctx.config.for_stage('analyze').coordinate_mode)
    prompt = prompts.render('analyze', mode=mode)
    contract = schema(size, mode)
    check = lambda v: compile_inventory(v, size, mode, ctx.run)
    evidence = {'version': VERSION, 'coordinate_mode': mode, 'first_pass_valid': False, 'repaired': False}
    try:
        value = ctx.client.ask('analyze', prompt, {'reference_size': size}, ctx.analysis_images(),
                                  contract, check, single_request=True, normalize_answer=normalize, reference_mode=mode)
        evidence['first_pass_valid'] = True
    except ModelError as error:
        evidence['first_error'] = str(error)
        candidates = ctx.candidates('analyze')
        prior = normalize(candidates[0]) if candidates else None
        plan = repair_plan(prior, size, mode)
        save(ctx.control/'structure-analysis.json', evidence)
        if plan:
            save(ctx.control/'structure-repair-plan.json', plan)
            patch = ctx.client.ask('analyze_repair', prompts.render('analyze_repair', mode=mode),
                                      {'reference_size': size, 'previous': prior, 'issues': plan['issues'],
                                       'allowed_updates': plan['fields']},
                                      ctx.analysis_images(), plan['schema'],
                                      lambda p: check(merge_repair(prior, p, plan)), single_request=True,
                                      normalize_answer=normalize_repair, reference_mode=mode)
            value = merge_repair(prior, patch, plan)
            evidence['repair_kind'] = 'field_patch'
        else:
            value = ctx.client.ask('analyze_repair', prompts.render('analyze_full_retry', mode=mode),
                                      {'reference_size': size, 'validation_error': str(error)}, ctx.analysis_images(),
                                      contract, check, single_request=True, normalize_answer=normalize, reference_mode=mode)
            evidence['repair_kind'] = 'full_retry'
        evidence['repaired'] = True
    bundle = check(value)
    save(ctx.run/'structure.json', {'version': VERSION, 'coordinate_mode': mode, **value})
    evidence.update(status='accepted', objects=len(bundle['analysis']['objects']),
                    generated_text_units=len(bundle['text_units']), aabb_geometry=True)
    evidence['normalizations'] = [read(p) for p in sorted((ctx.control/'vlm/analyze').glob('*/normalization-0.json'))]
    save(ctx.control/'structure-analysis.json', evidence)
    ctx.write_reference(bundle)


def schema(size, mode):
    number = {'type': 'number' if mode == 'normalized_1000' else 'integer',
              'minimum': 0, 'maximum': 1000 if mode == 'normalized_1000' else max(size)}
    item = contracts.obj({
        'id': ID, 'kind': {'enum': ['photo', 'overlay', 'frame', 'background', 'text']},
        'bbox': {'type': 'array', 'items': number, 'minItems': 4, 'maxItems': 4},
        'description': {'type': 'string', 'minLength': 1, 'maxLength': 400},
        'linked_to': ID,
        'photo_id': ID, 'parent_id': ID, 'text': {'type': ['string', 'null']},
        'color': COLOR, 'font': {'enum': ['sans', 'serif', 'mono', 'hand', 'cjk', 'cjk-hand']},
    }, ['id', 'kind', 'bbox'])
    item['allOf'] = [
        {'if': {'properties': {'kind': {'const': 'text'}}},
         'then': {'required': ['text']}, 'else': {'required': ['description']}},
        {'if': {'properties': {'kind': {'const': 'frame'}}}, 'then': {'required': ['photo_id']}},
        {'if': {'properties': {'kind': {'const': 'photo'}}},
         'else': {'properties': {'linked_to': False}}}]
    return contracts.obj({'objects': {'type': 'array', 'items': item, 'minItems': 1, 'maxItems': 160}})


def normalize(value):
    """Normalize containers and aliases without changing content or layer order."""
    result = unwrap_object(value, {'objects'})
    if not isinstance(result, dict) or not isinstance(result.get('objects'), list):
        return result
    rows = result['objects']
    if len(rows) == 1 and isinstance(rows[0], list) and all(isinstance(o, dict) for o in rows[0]):
        result['objects'] = rows[0]
    for item in result['objects']:
        if not isinstance(item, dict):
            continue
        for key in ('photo_id', 'parent_id', 'linked_to', 'color', 'font'):
            if key in item and item[key] is None:
                del item[key]
        for key, owner in (('text', 'text'),):
            if item.get('kind') != owner and item.get(key, 1) is None:
                del item[key]
        if 'fill' in item and 'color' not in item:
            item['color'] = item.pop('fill')
        if item.get('kind') == 'text' and item.get('description', 1) is None:
            del item['description']
    return result


def problems(value, size, mode):
    value = normalize(value)
    issues = []
    for e in Draft202012Validator(schema(size, mode)).iter_errors(value):
        path = list(e.absolute_path)
        issue = {'path': '.'.join(map(str, path)) or '$', 'message': e.message[:400]}
        if len(path) >= 2 and path[0] == 'objects' and isinstance(path[1], int):
            item = value['objects'][path[1]]
            if isinstance(item, dict) and isinstance(item.get('id'), str):
                issue['id'] = item['id']
                if e.validator == 'required':
                    issue['fields'] = [k for k in e.validator_value if k not in e.instance]
                elif len(path) >= 3 and e.validator != 'additionalProperties':
                    issue['fields'] = [path[2]]
        issues.append(issue)
    if not isinstance(value, dict) or not isinstance(value.get('objects'), list):
        return issues[:24]
    objects = value['objects']
    if not all(isinstance(o, dict) and isinstance(o.get('id'), str) for o in objects):
        return issues[:24]
    by_id = {o['id']: o for o in objects}
    indices = {o['id']: i for i, o in enumerate(objects)}
    if len(by_id) != len(objects):
        issues.append({'path': 'objects', 'message': 'Duplicate object IDs'})
    from photo_links import inventory_issues
    for issue in inventory_issues(objects, [o['id'] for o in objects]):
        issues.append({'path': 'objects.' + str(indices[issue['id']]), **issue})
    for i, item in enumerate(objects):
        def fail(message, fields=()):
            issues.append({'path': f'objects.{i}', 'id': item['id'], 'message': message,
                           'fields': list(fields)})
        box = item.get('bbox')
        if (isinstance(box, list) and len(box) == 4
                and all(isinstance(n, (int, float)) and not isinstance(n, bool) and math.isfinite(n) for n in box)):
            l, t, r, b = box; w, h = [1000, 1000] if mode == 'normalized_1000' else size
            if not (0 <= l < r <= w and 0 <= t < b <= h):
                fail('bbox must be nonempty and inside the reference', ['bbox'])
        kind = item.get('kind')
        if kind == 'frame':
            linked = by_id.get(item.get('photo_id')) if isinstance(item.get('photo_id'), str) else None
            if not linked or linked.get('kind') != 'photo':
                fail('frame needs photo_id pointing to a photo', ['photo_id'])
        elif 'photo_id' in item:
            fail('photo_id belongs to frame; use parent_id for photos on a shared backing')
        if 'parent_id' in item:
            owner = item['parent_id']
            if not isinstance(owner, str) or owner not in by_id or owner == item['id']:
                fail('parent_id must reference another existing object', ['parent_id'])
            else:
                visited = {item['id']}
                while isinstance(owner, str) and owner in by_id:
                    if owner in visited:
                        fail('parent_id must not form a cycle', ['parent_id']); break
                    visited.add(owner); owner = by_id[owner].get('parent_id')
        if kind == 'text':
            if 'text' not in item or (isinstance(item['text'], str) and not item['text'].strip()):
                fail('independent text requires readable text or null', ['text'])
        elif 'text' in item or 'font' in item:
            fail('text/font are only for independent text; describe fixed inscriptions on their carrier')
        if 'color' in item and kind not in {'text', 'background'}:
            fail('extracted objects do not need colour or drawing parameters')
    return issues[:24]


def compile_inventory(value, size, mode, run=None):
    value = normalize(value)
    issues = problems(value, size, mode)
    if issues:
        raise ValueError('; '.join(i['path'] + ': ' + i['message'] for i in issues))
    objects, units = [], []
    for source in value['objects']:
        item = {k: deepcopy(source[k]) for k in ('id', 'kind', 'bbox', 'description', 'photo_id', 'parent_id', 'linked_to') if k in source}
        if source['kind'] == 'text' and 'description' not in item:
            item['description'] = (source['text'] or '无法辨认的独立文字')[:400]
        if mode == 'normalized_1000':
            item['bbox'] = [round(v * size[i % 2] / 1000) for i, v in enumerate(item['bbox'])]
        item['label'] = item['description'][:30]
        kind = item['kind']
        item['method'] = 'extract' if kind in {'overlay', 'frame'} else 'local'
        if kind == 'background':
            item['background_type'] = 'simple_design' if source.get('color') else 'reference_clean'
            item['method'] = 'local' if source.get('color') else 'extract'
            if source.get('color'):
                item['style'] = {'fill': source['color']}
        if kind == 'text':
            item['text'] = source['text']
            item['text_status'] = 'known' if source['text'] else 'unreadable'
            item['style'] = {k: source[v] for k, v in [('fill', 'color'), ('font', 'font')] if v in source}
            units.append({'id': item['id'], 'bbox': deepcopy(item['bbox']), 'content': item['text'],
                          'treatment': 'plain_text', 'has_backing': False, 'decorative_lettering': False,
                          'edit_requested': False, 'text_id': item['id'], 'carrier_id': None,
                          'reason': 'Derived from the independent text object; no second VLM inventory.'})
        objects.append(item)
    result = {'analysis': {'schema_version': 'collage-analysis-v1', 'reference_size': list(size),
                          'objects': objects, 'layer_order': [o['id'] for o in objects]}, 'text_units': units}
    Draft202012Validator(contracts.REFERENCE).validate(result)
    if run is not None:
        contracts.validate_reference(result, run, geometry_warnings=[])
    return result


def repair_plan(original, size, mode):
    """Permit only fields identified by validation, never a whole-object rewrite."""
    original = normalize(original)
    if not isinstance(original, dict) or not isinstance(original.get('objects'), list):
        return None
    rows = original['objects']
    if not rows or not all(isinstance(o, dict) and isinstance(o.get('id'), str) for o in rows):
        return None
    if len({o['id'] for o in rows}) != len(rows):
        return None
    issues = problems(original, size, mode)
    fields = {}
    allowed = {'text', 'description', 'bbox', 'photo_id', 'parent_id', 'color', 'font'}
    for issue in issues:
        oid = issue.get('id'); names = issue.get('fields', [])
        if not oid or not names or set(names) - allowed:
            return None
        fields.setdefault(oid, set()).update(names)
    if not fields:
        return None
    definitions = schema(size, mode)['properties']['objects']['items']['properties']
    updates = {}
    for oid, names in fields.items():
        specifications = {k: deepcopy(definitions[k]) for k in sorted(names)}
        if 'parent_id' in specifications:
            specifications['parent_id'] = {'anyOf': [specifications['parent_id'], {'type': 'null'}]}
        updates[oid] = contracts.obj(specifications)
    return {'schema': contracts.obj({'updates': contracts.obj(updates)}),
            'fields': {k: sorted(v) for k, v in fields.items()}, 'issues': issues}


def normalize_repair(value):
    if (isinstance(value, list) and len(value) == 1 and isinstance(value[0], dict)
            and 'updates' in value[0]):
        return deepcopy(value[0])
    return deepcopy(value)


def merge_repair(original, patch, plan):
    Draft202012Validator(plan['schema']).validate(patch)
    result = deepcopy(original)
    by_id = {o['id']: o for o in result['objects']}
    for oid, changes in patch.get('updates', {}).items():
        by_id[oid].update(deepcopy(changes))
    return normalize(result)

collage/workflow/stages/bind.py.text:
"""阶段 4：照片槽 + 客户素材 -> 选材与裁切。一次请求，失败停止制作。"""

from copy import deepcopy
from jsonschema import Draft202012Validator
from collage import contracts, prompts
from collage.storage import read, save


VERSION = 'photo-binding-v9-1'


def execute(ctx):
    ctx.progress(2, 'running', 'VLM 一次完成客户照片观察、选材与裁切，仅处理 photo 槽')
    structure = read_structure(ctx.run, ctx.config)
    windows = read(ctx.run/'photo-windows.json') if (ctx.run/'photo-windows.json').exists() else None
    evidence = {'contract': VERSION, 'status': 'running',
                'photo_count': sum(o['kind'] == 'photo' for o in structure['objects']),
                'texts_policy': 'disabled',
                'automatic_retry': False, 'automatic_repair': False}
    save(ctx.control/'binding-check.json', evidence)
    before = ctx.client.usage()['requests']
    try:
        context = context_for(ctx.input_context(), structure, windows)
        schema = schema_for(context, windows)
        save(ctx.control/'binding-input.json', context)
        if context['photo_slots']:
            answer = ctx.client.ask('bind', prompts.render('bind'), context,
                ctx.analysis_images()+ctx.material_images(), schema,
                lambda value: validate(value, context, structure, ctx.run, windows),
                single_request=True, reference_input_only=True)
        else:
            answer = {'photos': []}
        value = validate(answer, context, structure, ctx.run, windows)
    except Exception as exc:
        evidence.update(status='failed', error=str(exc)[:1500],
                        requests_this_execution=ctx.client.usage()['requests']-before)
        save(ctx.control/'binding-check.json', evidence)
        raise
    save(ctx.run/'bindings.json', value)
    # The full renderer still uses this internal file for its progress gate.
    # Standalone binding only needs structure.json, windows and customer materials.
    if (ctx.run/'analysis.json').is_file():
        ctx.command('validate')
    evidence.update(status='accepted', requests_this_execution=ctx.client.usage()['requests']-before)
    save(ctx.control/'binding-check.json', evidence)
    ctx.progress(2, 'complete', '照片绑定已校验并保存，文字绑定为空，进入制作')


def read_structure(run, config):
    """Read the public inventory; normalize geometry without depending on analysis.json."""
    from collage.vlm.coordinates import resolve_mode
    structure = read(run/'structure.json')
    if not isinstance(structure.get('objects'), list):
        raise ValueError('Photo binding requires structure.json with an objects array')
    stage = config.for_stage('analyze')
    mode = structure.get('coordinate_mode', resolve_mode(stage.model, stage.coordinate_mode))
    if mode not in {'pixel', 'normalized_1000'}:
        raise ValueError('Unknown structure coordinate mode: ' + str(mode))
    if mode == 'normalized_1000':
        size = read(run/'input.json')['reference_size']
        for photo in structure['objects']:
            if photo['kind'] == 'photo':
                photo['bbox'] = [v * size[i % 2] / 1000 for i, v in enumerate(photo['bbox'])]
    return structure


def context_for(base, structure, windows=None):
    """Expose photo descriptions and geometry, with only one derived subject requirement."""
    slots = []
    for photo in structure['objects']:
        if photo['kind'] != 'photo':
            continue
        row = {key: deepcopy(photo[key]) for key in
               ('description', 'bbox', 'rotation', 'linked_to') if key in photo}
        l, t, r, b = photo['bbox']
        if r <= l or b <= t:
            raise ValueError(photo['id'] + ': photo slot must have positive area')
        row.update(slot_id=photo['id'], aspect_ratio=round((r-l)/(b-t), 6))
        slots.append(row)
    ids = [p['slot_id'] for p in slots]
    if len(ids) != len(set(ids)):
        raise ValueError('Duplicate photo slot ID')
    result = {'reference_size': deepcopy(base['reference_size']),
              'instructions': base.get('instructions', ''), 'photo_slots': slots,
              'catalog': [{key: deepcopy(asset[key]) for key in ('id', 'size')}
                          for asset in base['catalog']]}
    if not slots:
        return result
    if windows is None:
        raise ValueError('Photo binding requires a completed photo window plan')
    from photo_windows import validate_plan
    validate_plan(windows)
    specs = [spec for spec in windows['photos'] if spec['photo_id'] in ids]
    window_ids = [p['photo_id'] for p in specs]
    if len(window_ids) != len(set(window_ids)) or set(window_ids) != set(ids):
        raise ValueError('Photo window plan must cover each photo slot exactly once')
    by_id = {p['slot_id']: p for p in slots}
    for spec in specs:
        slot = by_id[spec['photo_id']]
        linked = spec.get('linked_to')
        if slot.get('linked_to') and linked != slot['linked_to']:
            raise ValueError('Photo window plan must retain the structure linked_to')
        if linked:
            slot['linked_to'] = linked
        subject = spec['subject']
        slot['requires_segmentable_subject'] = (not subject['preserve_background']
                                                 or subject['stroke']['enabled'])
    for slot in slots:
        linked = slot.get('linked_to')
        if not linked:
            continue
        if linked not in by_id or linked == slot['slot_id'] or by_id[linked].get('linked_to'):
            raise ValueError('linked_to must name an independent photo slot')
        base_slot = by_id[linked]
        base_slot['requires_segmentable_subject'] |= slot['requires_segmentable_subject']
    return result


def schema_for(context, windows=None):
    item = deepcopy(contracts.BINDING_PLAN['properties']['photos']['items'])
    slots = [p['slot_id'] for p in context['photo_slots']]
    assets = [a['id'] for a in context['catalog']]
    if slots and not assets:
        raise ValueError('Photo binding requires customer assets')
    for field, values in [('slot_id', slots), ('asset_id', assets)]:
        if values:
            item['properties'][field]['enum'] = values
    item['properties']['reason']['minLength'] = 1
    # Keep rendering details local. Only the required crop reaches the output contract.
    specs = {p['photo_id']: p for p in (windows or {}).get('photos', [])}
    full_crop = [p['slot_id'] for p in context['photo_slots']
                 if p['slot_id'] in specs and not p.get('linked_to')
                 and not specs[p['slot_id']]['subject']['preserve_background']]
    if full_crop:
        item['allOf'] = [{'if': {'properties': {'slot_id': {'enum': full_crop}},
                                'required': ['slot_id']},
                          'then': {'properties': {'source_crop': {'const': [0, 0, 1, 1]}}}}]
    return contracts.obj({'photos': {'type': 'array', 'items': item,
                                     'minItems': len(slots), 'maxItems': len(slots)}})


def validate(answer, context, structure, run, windows=None):
    """Reject rather than repair model output. Never mutate the caller's answer."""
    if windows is None:
        windows = read(run/'photo-windows.json')
    Draft202012Validator(schema_for(context, windows)).validate(answer)
    by_id = {p['slot_id']: p for p in answer['photos']}
    if len(by_id) != len(answer['photos']) or set(by_id) != {p['slot_id'] for p in context['photo_slots']}:
        raise ValueError('photos must cover every photo slot exactly once')
    for slot in context['photo_slots']:
        oid = slot['slot_id']; row = by_id[oid]
        if not row['reason'].strip():
            raise ValueError(oid + ': reason must describe visible evidence and crop choice')
        linked = slot.get('linked_to')
        if linked:
            for field in ('asset_id', 'source_crop', 'crop_center', 'mirror_x'):
                if row[field] != by_id[linked][field]:
                    raise ValueError(f'{oid}: {field} must match linked base {linked}')
    value = {'schema_version': 'collage-bindings-v1', 'photos': deepcopy(answer['photos']), 'texts': []}
    contracts.validate_bindings(value, structure, run)
    return value

collage/workflow/stages/build.py.text:
"""阶段 5：分析、窗口、绑定 -> 素材提取与本地合成；不调用结构化 VLM。"""

from collage.storage import read
from collage.workflow.context import CommandError


def execute(ctx):
    ctx.progress(3, 'running', '按固定计划提取装饰并本地合成')
    needed = any(o.get('method') == 'extract' for o in read(ctx.run/'analysis.json')['objects'])
    try:
        if needed and ctx.reveal:
            ctx.command('build', '--reveal', '--reveal-layout', 'full', '--reveal-key-file', ctx.config.reveal_key_file)
        else:
            ctx.command('build', '--no-reveal')
    except CommandError as exc:
        ctx.warn('build_fallback', 'build', '制作失败，尝试保留布局的本地合成：' + str(exc))
        try:
            ctx.command('build', '--no-reveal')
        except CommandError as local_exc:
            ctx.draft('布局无法完成渲染，改为简化拼图：' + str(local_exc))
            ctx.command('build', '--no-reveal')
    for item in read(ctx.run/'result.json').get('resources', []):
        if item.get('metadata', {}).get('fallback'):
            ctx.warn('asset_fallback', 'build', item['id'] + '：' + item['metadata'].get('note', '素材已降级'))
    ctx.progress(3, 'complete', '首版已合成，进入素材筛选')

collage/workflow/stages/photo_windows.py.text:
"""阶段 2：对象清单 + 参考图/裁片 -> 照片摆放、窗口形状、主体处理和效果。"""

from copy import deepcopy
from collage import contracts
from collage import prompts
from collage.vlm.client import ModelError
from collage.storage import read, save


VERSION = 'window-drawing-v9-3'


class StructureRepairRequired(RuntimeError):
    """Stop when photo/frame structure cannot express the observed windows."""


def input_analysis(analysis):
    """Only photo/frame design data crosses this model boundary."""
    fields = ('id', 'kind', 'bbox', 'description', 'photo_id', 'linked_to', 'parent_id')
    rows = [{k: deepcopy(o[k]) for k in fields if k in o}
            for o in analysis['objects'] if o['kind'] in {'photo', 'frame'}]
    ids = {o['id'] for o in rows}
    for row in rows:
        if row.get('parent_id') not in ids:
            row.pop('parent_id', None)
    return {'objects': rows, 'layer_order': [oid for oid in analysis['layer_order'] if oid in ids]}


def execute(ctx):
    from photo_windows import defaults, reference_crops, previews
    current = {'analysis': read(ctx.run/'analysis.json'), 'text_units': read(ctx.run/'text-units.json', [])}
    crops, regions = reference_crops(ctx.run, current['analysis'])
    def validate(answer):
        # A valid report of missing structure is useful evidence, not malformed JSON.
        if not answer.get('structure_issues'):
            compile_response(answer, current, ctx.run)
    evidence = {'version': VERSION}
    try:
        if crops:
            answer = ctx.client.ask('photo_windows', prompts.render('photo_windows'),
                {**ctx.reference_context(), 'analysis': input_analysis(current['analysis']), 'crop_regions': regions},
                ctx.analysis_images()+crops, schema(), validate)
            if answer.get('structure_issues'):
                evidence.update(status='structure_repair_required', answer=answer,
                                structure_issues=answer['structure_issues'])
                save(ctx.control/'window-geometry.json', evidence)
                ctx.warn('window_structure_unresolved', 'photo_windows', '；'.join(answer['structure_issues']))
                raise StructureRepairRequired('照片窗口结构需要修正：' + '；'.join(answer['structure_issues']))
            value, plan, notes = compile_response(answer, current, ctx.run)
            evidence.update(status='accepted', answer=answer, notes=notes)
            ctx.write_reference(value)
        else:
            value, plan, notes = current, defaults(current['analysis']), []
            evidence.update(status='no_photos', notes=[])
    except ModelError as exc:
        value, plan, notes = current, defaults(current['analysis']), []
        evidence.update(status='fallback', error=str(exc), notes=[])
        ctx.warn('window_geometry_unresolved', 'photo_windows',
                    '窗口绘制参数未确认，临时保留第一步水平范围与明确关联；描边和渐变不猜参数：' + str(exc))
    assessed = evidence['status'] == 'accepted'
    evidence['drawing_review'] = drawing_review(plan, assessed=assessed)
    pending = [row for row in evidence['drawing_review'] if row['status'] == 'needs_visual_review']
    if pending:
        evidence['status'] = 'needs_visual_review'
        for row in pending:
            ctx.warn('window_boundary_review', 'photo_windows', row['photo_id'] + '：' + row['review_reason'])
    initial = {o['id']: o for o in current['analysis']['objects']}
    evidence['link_review'] = [
        {'photo_id': p['photo_id'], 'initial_linked_to': initial[p['photo_id']].get('linked_to'),
         'applied_linked_to': p.get('linked_to'),
         'status': 'assessed' if assessed else 'unresolved'}
        for p in plan['photos'] if p.get('linked_to') or initial[p['photo_id']].get('linked_to')]
    save(ctx.control/'window-geometry.json', evidence)
    for note in notes:
        ctx.warn('seam_adjusted', 'photo_windows', note)
    save(ctx.run/'photo-windows.json', plan)
    previews(ctx.run, value['analysis'], plan)


def schema():
    from window_contract import SCHEMA
    result = deepcopy(SCHEMA)
    row = result['properties']['photos']['items']
    row['properties']['placement'] = contracts.obj({
        'bbox': deepcopy(contracts.ANALYSIS['properties']['objects']['items']['properties']['bbox']),
        'rotation': {'type': 'number', 'minimum': -180, 'maximum': 180}})
    row['required'].append('placement')
    result['properties']['structure_issues'] = {'type': 'array', 'maxItems': 12,
        'items': {'type': 'string', 'minLength': 1, 'maxLength': 500},
        'description': '仅输入 photo/frame 明确不存在、重复，或缺少必要前景层/关联错误使效果无法表达时填写，说明相关 ID 与可见依据；不校验前后层级，不报告局部参数不确定。正常时省略或为空；非空时 photos 可为空。'}
    result['properties']['frame_fallbacks'] = {'type': 'array', 'items': contracts.obj({
        'frame_id': contracts.IDENTIFIER,
        'fill': {'type': 'string', 'pattern': '^#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$'},
        'radius': {'type': 'number', 'minimum': 0, 'maximum': .5}}, ['frame_id', 'fill'])}
    return result


def compile_response(answer, current, run=None):
    from photo_windows import resolve_seams
    from window_contract import execution_spec
    value = deepcopy(current)
    plan = deepcopy(answer)
    if plan.pop('structure_issues', []):
        raise StructureRepairRequired('Window assessment reported an incorrect photo/frame structure')
    objects = {o['id']: o for o in value['analysis']['objects']}
    expected = {oid for oid, o in objects.items() if o['kind'] == 'photo'}
    ids = [p['photo_id'] for p in plan['photos']]
    if len(ids) != len(set(ids)) or set(ids) != expected:
        raise ValueError('Window plan must include every photo exactly once')
    for spec in plan['photos']:
        if not isinstance(spec.get('reason'), str) or not spec['reason'].strip():
            raise ValueError(spec['photo_id'] + ': window reason must explain visible drawing parameters')
        placement = spec.pop('placement')
        item = objects[spec['photo_id']]
        if item.get('linked_to'):
            spec.setdefault('linked_to', item['linked_to'])
        if spec.get('linked_to') and execution_spec(spec)['shape']['type'] != 'rectangle':
            raise ValueError(spec['photo_id'] + ': linked foreground shape must be rectangle; '
                             'the subject segmentation supplies the silhouette, not a polygon traced from the reference')
        old = item['bbox']; new = placement['bbox']
        if min(old[2], new[2]) <= max(old[0], new[0]) or min(old[3], new[3]) <= max(old[1], new[1]):
            raise ValueError(item['id'] + ': photo placement must overlap its observed location')
        item.update(bbox=new, rotation=placement['rotation'])
    seen = set()
    for fallback in plan.pop('frame_fallbacks', []):
        oid = fallback['frame_id']
        if oid in seen or oid not in objects or objects[oid]['kind'] != 'frame':
            raise ValueError('frame_fallbacks must name distinct existing frames')
        seen.add(oid)
        objects[oid]['style'] = {k: v for k, v in fallback.items() if k != 'frame_id'}
    if run is not None:
        contracts.validate_reference(value, run, geometry_warnings=[])
    plan, notes = resolve_seams(plan, value['analysis'])
    return value, plan, notes


def drawing_review(plan, *, assessed):
    rows = []
    for spec in plan['photos']:
        row = {**spec, 'status': 'assessed' if assessed else 'unresolved'}
        mask = spec['mask']
        if (assessed and not spec['subject']['preserve_background'] and mask['enabled']
                and mask['shape']['type'] == 'polygon' and mask['stroke']['enabled']):
            row.update(status='needs_visual_review',
                       review_reason='去背景主体叠加多边形窗口描边：需确认存在独立固定窗口，不能以参考主体轮廓代替客户分割；参数暂不改写。')
        rows.append(row)
    return rows

